"""Learn when to deploy the original joint workforce/input/route planner."""
_FRONTIER_HISTORY={}
_FRONTIER_STATE={}


def _frontier_features(obs,plan):
    features=_ml_features(obs,_FRONTIER_HISTORY.get(obs['player'],{}))
    features += [plan['predicted_net']/10000,plan['hire_cost']/1000,
                 plan['unassigned']/100,plan['planned_workers']/20,plan['input_purchase']/50]
    totals={item:0 for item in _ML_PRODUCTS}
    for route in plan['plans']:
        for item,q in route['products'].items():totals[item]+=q
    features += [totals[item]/100 for item in _ML_PRODUCTS]
    return features


def _frontier_choose(features,model):
    values=sorted(_ml_tree_predict(t,features)[1] for t in model['trees'])
    return int(values[int(model['quantile']*(len(values)-1))]>model['threshold'])


def _frontier_before(obs,configuration):
    step=obs['step'];seat=obs['player']
    if step==0:_FRONTIER_HISTORY.pop(seat,None);_FRONTIER_STATE.pop(seat,None)
    if step==648:_FRONTIER_HISTORY[seat]=dict(obs['market']['inventory'])
    if step!=696:return
    plan=_au_plan(obs,configuration)
    features=_frontier_features(obs,plan)
    choice=_FRONTIER_FORCE if _FRONTIER_FORCE is not None else _frontier_choose(features,_FRONTIER_MODEL)
    _FRONTIER_STATE[seat]=dict(features=features,choice=choice)
    if choice:_AU_STATE[seat]=plan


_FRONTIER_PARENT=agent
def agent(observation,configuration=None):
    _frontier_before(observation,configuration)
    st=_FRONTIER_STATE.get(observation['player'],{})
    # The inherited auction wrapper is bypassed when the learned selector abstains.
    if observation['step']>=696 and not st.get('choice',0):
        action=_AU_PARENT(observation,configuration)
        telemetry=getattr(_AU_PARENT,'telemetry',{})
    else:
        action=_FRONTIER_PARENT(observation,configuration)
        telemetry=getattr(_FRONTIER_PARENT,'telemetry',{})
    _FRONTIER_TELEMETRY.clear()
    _FRONTIER_TELEMETRY.update(telemetry)
    _FRONTIER_TELEMETRY.update(frontier_choice=st.get('choice',0),frontier_decisions=int(bool(st)))
    return action
_FRONTIER_TELEMETRY={}
agent.telemetry=_FRONTIER_TELEMETRY
agent=globals().pop('agent')

_F2_THRESHOLD=250
_F2_STAGGER=1
_FRONTIER_FORCE=1
"""Sell valuable cargo when a route crosses the shed, retaining future inputs."""
_F2_OLD_JOBS=_au_jobs


def _au_jobs(obs):
    jobs=_F2_OLD_JOBS(obs)
    for y,row in enumerate(obs['farms'][obs['player']]['tiles']):
        for x,t in enumerate(row):
            if not isinstance(t,dict) or t.get('crop') not in ('WHEAT','CARROT','MELON'):continue
            if t.get('yield_units',0)!=0 or t.get('watered_today'):continue
            crop=t['crop'];first,last,cap=_AU_CROPS[crop];age=obs['day']-t['planted_day']
            if max(first,(last+1)//2)<=age<=last:
                active=t.get('fertilized_until_day',-1)>=obs['day']
                jobs[x,y]=[([['WATER'],['HARVEST']],{crop:2 if active else 1})]
                if not active:jobs[x,y].append(([['FERTILIZE'],['WATER'],['HARVEST']],{crop:2,'FERTILIZER':-1}))
    return jobs


def _f2_walk(pos,target,cargo,prices):
    cursor=tuple(pos);commands=[];remaining=dict(cargo)
    for move in _au_walk(pos,target):
        if cursor in _AU_HOME:
            # PLACE transfers one selected product and keeps fertilizer for tasks
            # later in this trip. DROP would silently offload those inputs too.
            for item,q in sorted(remaining.items(),key=lambda kv:-prices[kv[0]]*kv[1]):
                if item!='FERTILIZER' and q*prices[item]>=_F2_THRESHOLD:
                    commands.append(['PLACE',item,q]);remaining[item]=0
        commands.append(move)
        x,y=cursor;op=move[0]
        cursor=(x+int(op=='EAST')-int(op=='WEST'),y+int(op=='SOUTH')-int(op=='NORTH'))
    return commands,remaining


def _au_route(pos,start,jobs,prices,power,bias,end=719,input_cap=100):
    left=dict(jobs);chosen=[];commands=[];value=0.;products={};cargo={};cursor=tuple(pos);inputs=0
    while left:
        best=None
        for target,variants in left.items():
            walk,delivered_cargo=_f2_walk(cursor,target,cargo,prices)
            home_distance=_au_dist(target,_au_home(target))
            for ops,goods in variants:
                need=int(goods.get('FERTILIZER',0)<0)
                if need and (tuple(pos) not in _AU_HOME or inputs+need>input_cap):continue
                setup=int(need>0 and inputs==0)
                duration=len(walk)+len(ops)+setup
                if start+len(commands)+duration+home_distance+1>end:continue
                gain=sum(prices[k]*v for k,v in goods.items())
                cost=max(.5,duration+bias*(home_distance-_au_dist(cursor,_au_home(cursor))))
                rank=(gain/(cost**power),gain,-duration,-target[1],-target[0])
                if best is None or rank>best[0]:best=(rank,target,ops,goods,gain,need,walk,delivered_cargo)
        if best is None:break
        _,target,ops,goods,gain,need,walk,cargo=best
        if need and inputs==0:commands.insert(0,['PICKUP','FERTILIZER',0])
        inputs+=need;commands+=walk+ops;cursor=target
        value+=gain;chosen.append(target);left.pop(target)
        for item,q in goods.items():
            products[item]=products.get(item,0)+q
            if q>0:cargo[item]=cargo.get(item,0)+q
    if chosen:commands+=_au_walk(cursor,_au_home(cursor))+[['DROP']]
    if inputs:commands[0][2]=inputs
    return dict(start=start,origin=list(pos),commands=commands,jobs=chosen,value=value,products=products,inputs=inputs)


_F2_OLD_ACTION=_au_action
def _au_action(obs,config,state):
    action=_F2_OLD_ACTION(obs,config,state)
    farm=obs['farms'][obs['player']];positions=[farm['farmer'],*farm['hands']]
    commands=[action['farmer'],*action['hands']]
    projected=dict(obs['private']['shed'])
    for i,(cmd,pos) in enumerate(zip(commands,positions)):
        if tuple(pos) not in _AU_HOME:continue
        inv=obs['private']['inventories'][i]
        if cmd[0]=='DROP':
            for item,q in inv.items():
                take=min(q,max(0,100-sum(projected.values())))
                projected[item]=projected.get(item,0)+take
        elif cmd[0]=='PLACE' and len(cmd)>2:
            item=cmd[1];take=min(cmd[2],inv.get(item,0),max(0,100-sum(projected.values())))
            projected[item]=projected.get(item,0)+take
        elif cmd[0]=='PICKUP':projected[cmd[1]]=max(0,projected.get(cmd[1],0)-cmd[2])
    reserve=sum(p['inputs'] for p in state['plans'] if p['inputs'] and obs['step']<p['start'])
    projected['FERTILIZER']=max(0,projected.get('FERTILIZER',0)-reserve)
    other=[o for o in action['market'] if o[0]!='SELL']
    sales=[['SELL',k,v] for k,v in projected.items() if v>0 and k in obs['market']['prices']]
    sales.sort(key=lambda o:(-_r37_quote_priority(obs,o,projected),-o[2]*obs['market']['prices'][o[1]]))
    action['market']=sales[:10-len(other)]+other
    state['early_deliveries']=state.get('early_deliveries',0)+sum(c[0]=='PLACE' for c in commands)
    return action


_F2_PARENT=agent
def agent(observation,configuration=None):
    action=_F2_PARENT(observation,configuration)
    state=_AU_STATE.get(observation['player'],{})
    _F2_TELEMETRY.clear()
    _F2_TELEMETRY.update(getattr(_F2_PARENT,'telemetry',{}))
    _F2_TELEMETRY['early_deliveries']=state.get('early_deliveries',0)
    return action
_F2_TELEMETRY={}
agent.telemetry=_F2_TELEMETRY
agent=globals().pop('agent')

# Apache-2.0: funding/seed guards adapted from Ahmed Berat Ozer V41.
# Opening lineage: Rayk Kretzschmar; integration/capacity solver: Arturo-GA.
def _r97_budget(obs,orders):
    farm=obs['farms'][obs['player']];cost=0;hires=int(farm['hires_today'])
    # At most ten 100-unit purchases per opponent turn. The additional 1000
    # own units give an intentionally conservative upper bound on buy quotes.
    prices={p:_r37_market_price(p,obs['market']['inventory'][p]-2000) for p in ('WHEAT','FERTILIZER')}
    for order in orders:
        if not order:continue
        op=order[0]
        if op=='HIRE':cost+=_v219_fib(hires);hires+=1
        elif op=='BUY_LAND':cost+=4000
        elif len(order)>2:
            item=order[1];q=max(0,int(order[2]))
            if op=='BUY_PRODUCT':cost+=q*prices[item]
            elif op=='BUY_ANIMAL':cost+=q*{'GOOSE':300,'COW':400,'SHEEP':500}[item]
            elif op=='BUY_SEED':cost+=q*{'WHEAT':10,'CARROT':20,'TOMATO':50,'STRAWBERRY':100,'MELON':80}[item]
    return cost<=farm['money']

def _r124_labor_reserve(native):
    n=sum(bool(o) and o[0]=='HIRE' for o in native[24].get('market',[]))
    return sum(_v219_fib(i) for i in range(n)),n

def _r124_seed_budget(obs,action,reserve):
    if not any(o and o[0]=='BUY_SEED' for o in action.get('market',[])):return action
    player=int(obs['player']);budget=dict(obs,farms=[dict(f) for f in obs['farms']]);budget['farms'][player]['money']-=reserve
    if _r97_budget(budget,action.get('market',[])):return action
    result=copy.deepcopy(action)
    for i in range(len(result['market'])-1,-1,-1):
        order=result['market'][i]
        if len(order)<3 or order[0]!='BUY_SEED':continue
        before=max(0,int(order[2]));order[2]=before
        while order[2]>0 and not _r97_budget(budget,result['market']):order[2]-=1
        n=before-order[2]
        if n:
            _R124_REPORT['opening_seed_budget_units']+=n
            _R124_REPORT['opening_seed_budget_cost']+=n*{'WHEAT':10,'CARROT':20,'TOMATO':50,'STRAWBERRY':100,'MELON':80}[order[1]]
        if _r97_budget(budget,result['market']):break
    return result

def _r124_atomic(obs,action,state):
    commands=[action.get('farmer') or ['PASS'],*(action.get('hands') or [])]
    demand={}
    for c in commands:
        if len(c)>1 and c[0]=='PLANT':demand[c[1]]=demand.get(c[1],0)+1
    if not demand:return action
    available=obs['private']['seeds'];blocked={p for p,n in demand.items() if n>available.get(p,0)}
    farm,private=_PLANNER_NS['_clone_state'](obs['farms'][obs['player']],obs['private'])
    changed=False;kept=[]
    for actor,c in enumerate(commands):
        if len(c)>1 and c[0]=='PLANT':
            pos=None if actor>=len(private['inventories']) else farm['farmer'] if actor==0 else farm['hands'][actor-1]
            valid=pos is not None and farm['tiles'][pos[1]][pos[0]] is None and private['seeds'].get(c[1],0)>0
            if not valid:
                commands[actor]=['PASS'];changed=True;_R124_REPORT['opening_atomic_dropped']+=1
            elif c[1] in blocked:
                kept.append(dict(xy=list(pos),crop=c[1],birth=int(obs["step"])//24));_R124_REPORT['opening_atomic_rescued_requests']+=1
        if actor<len(private['inventories']):_PLANNER_NS['_apply_unit_action'](farm,private,actor,commands[actor],10,int(obs["step"])//24,24,100)
    if kept:state['pending_plants']=kept
    if changed:
        action=dict(action,farmer=commands[0],hands=commands[1:])
    return action

"""Allocate the shared shed capacity across terminal deposit commands.

Original multiple-choice knapsack on physical inventories. Each unit may DROP
all its cargo, PLACE one product, or retain its cargo. No destructive partial
DROP is permitted. Quote values are estimates; future/rival private stock is
not observed. Orders are recomputed from exact resulting own field state.
"""


def _f3_capacity(obs,action):
    farm=obs['farms'][obs['player']];private=obs['private']
    positions=[farm['farmer'],*farm['hands']]
    commands=[action.get('farmer') or ['PASS'],*(action.get('hands') or [])]
    eligible=[i for i,(pos,c) in enumerate(zip(positions,commands))
              if tuple(pos) in _AU_HOME and c[0] in ('DROP','PASS') and private['inventories'][i]]
    if not eligible:return action
    # Fixed commands reserve capacity before distributing the remaining room.
    projected_farm,projected_private=_PLANNER_NS['_clone_state'](farm,private)
    fixed=list(commands)
    for i in eligible:fixed[i]=['PASS']
    for i,c in enumerate(fixed[:len(private['inventories'])]):
        _PLANNER_NS['_apply_unit_action'](projected_farm,projected_private,i,c,10,29,24,100)
    room=max(0,100-sum(projected_private['shed'].values()))
    total=sum(sum(private['inventories'][i].values()) for i in eligible)
    if total<=room:return action
    prices=obs['market']['prices']
    # dp[used] = estimated value, path. Equal-value choices use less capacity.
    dp={0:(0.,())}
    for i in eligible:
        inv=private['inventories'][i]
        options=[(0,0.,['PASS'])]
        n=sum(inv.values())
        if n<=room:
            options.append((n,sum(prices.get(p,0)*q for p,q in inv.items()),['DROP']))
        for item,q in sorted(inv.items()):
            if item not in prices or q<=0:continue
            for take in range(1,min(int(q),room)+1):
                options.append((take,prices[item]*take,['PLACE',item,take]))
        updated={}
        for used,(value,path) in dp.items():
            for count,gain,cmd in options:
                key=used+count
                if key>room:continue
                proposal=(value+gain,path+(cmd,))
                if key not in updated or proposal[0]>updated[key][0]:updated[key]=proposal
        dp=updated
    used,(_,chosen)=max(dp.items(),key=lambda pair:(pair[1][0],-pair[0]))
    result=copy.deepcopy(action)
    result_commands=[result.get('farmer') or ['PASS'],*(result.get('hands') or [])]
    for i,c in zip(eligible,chosen):result_commands[i]=c
    result['farmer'],result['hands']=result_commands[0],result_commands[1:]
    pf,pp=_PLANNER_NS['_clone_state'](farm,private)
    for i,c in enumerate(result_commands[:len(private['inventories'])]):
        _PLANNER_NS['_apply_unit_action'](pf,pp,i,c,10,29,24,100)
    projected=dict(pp['shed'])
    state=_AU_STATE.get(obs['player'],{})
    reserve=sum(p['inputs'] for p in state.get('plans',[]) if p['inputs'] and obs['step']<p['start'])
    projected['FERTILIZER']=max(0,projected.get('FERTILIZER',0)-reserve)
    other=[o for o in result.get('market',[]) if o and o[0]!='SELL']
    sales=[['SELL',p,q] for p,q in projected.items() if q>0 and p in prices]
    sales.sort(key=lambda o:(-_r37_quote_priority(obs,o,projected),-o[2]*prices[o[1]],o[1]))
    result['market']=sales[:max(0,10-len(other))]+other
    _R124_REPORT['f3_capacity_turns']+=1
    _R124_REPORT['f3_deposit_units_deferred']+=total-used
    return result

_F3_CAPACITY=True
"""Observed-resource contracts around Frontier, Apache-2.0.

Funding and atomic planting helpers adapted from Ahmed Berat Ozer's V41;
opening credited there to Rayk Kretzschmar. General-day seed validation,
integration and confirmed-effect telemetry: Arturo-GA / Kaggriculture Lab.
"""
_F3_PARENT=agent
_F3_STATES={}
_R124_REPORT={}


def agent(observation,configuration=None):
    action=_F3_PARENT(observation,configuration)
    player=int(observation['player']);step=int(observation['step'])
    state=_F3_STATES.get(player)
    if state is None or step<=state['step']:
        state=_F3_STATES[player]={'step':-1,'pending_plants':[]}
        _R124_REPORT.clear()
        _R124_REPORT.update(opening_seed_budget_units=0,opening_seed_budget_cost=0,
            opening_atomic_dropped=0,opening_atomic_rescued_requests=0,
            opening_atomic_rescued_confirmed=0,opening_atomic_plant_errors=0,
            opening_day1_cash=0,opening_day1_hires_requested=0,
            opening_day1_hires_confirmed=0,opening_day1_hire_shortfalls=0,
            f3_resource_errors=0,f3_capacity_turns=0,f3_deposit_units_deferred=0)
    state['step']=step
    farm=observation['farms'][player]
    for p in state.pop('pending_plants',[]):
        x,y=p['xy'];tile=farm['tiles'][y][x]
        if isinstance(tile,dict) and tile.get('crop')==p['crop'] and tile.get('planted_day')==p['birth']:
            _R124_REPORT['opening_atomic_rescued_confirmed']+=1
        else:_R124_REPORT['opening_atomic_plant_errors']+=1
    standard=all((configuration or {}).get(k,v)==v for k,v in
        [('boardSize',10),('episodeSteps',720),('turnsPerDay',24),('shedCapacity',100),
         ('maxMarketOrdersPerTurn',10),('farmHandCostMult',1)])
    if standard:
        original=action
        try:
            if step<24:
                native=_ROUTES[_IMPL.chassis.players[player]['route']]
                reserve,_=_r124_labor_reserve(native)
                action=_r124_seed_budget(observation,action,reserve)
            if step<696:action=_r124_atomic(observation,action,state)
            if _F3_CAPACITY and step>=716:action=_f3_capacity(observation,action)
        except Exception:
            _R124_REPORT['f3_resource_errors']+=1
            action=original
    if step==24:
        _R124_REPORT['opening_day1_cash']=farm['money']
        state['hires']=sum(bool(o) and o[0]=='HIRE' for o in action.get('market',[]))
        _R124_REPORT['opening_day1_hires_requested']=state['hires']
    if step==25:
        _R124_REPORT['opening_day1_hires_confirmed']=len(farm['hands'])
        _R124_REPORT['opening_day1_hire_shortfalls']=max(0,state.get('hires',0)-len(farm['hands']))
    agent.telemetry=dict(getattr(_F3_PARENT,'telemetry',{}),**_R124_REPORT)
    return action


agent.telemetry={}
agent=globals().pop('agent')
